saffron_gym_navigator.agent_input_schema:
{
  "type": "object",
  "properties": {
    "current_room": {
      "type": "string",
      "description": "The current room the player is in (e.g. Entrance, SE, NE, NW, W, N, Center, E, SW)"
    },
    "target_room": {
      "type": "string",
      "description": "The desired destination room (e.g. Center Room / Sabrina)"
    },
    "known_warp_matrix": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "source_room": {"type": "string"},
          "warp_coord": {"type": "string"},
          "destination_room": {"type": "string"},
          "dest_coord": {"type": "string"}
        },
        "required": ["source_room", "warp_coord", "destination_room", "dest_coord"]
      },
      "description": "List of empirically verified warp connections"
    }
  },
  "required": ["current_room", "target_room", "known_warp_matrix"]
}

saffron_gym_navigator.agent_output_schema:
{
  "type": "object",
  "properties": {
    "recommended_path": {
      "type": "array",
      "items": {"type": "string"},
      "description": "Step-by-step sequence of room transitions and warp coordinates to reach the target room"
    },
    "combat_preparation": {
      "type": "string",
      "description": "Move and item recommendations for upcoming battles"
    }
  },
  "required": ["recommended_path", "combat_preparation"]
}
